/*
 * Digital SAT mock exam engine.
 * Reads window.SAT_EXAM (generated by scripts/build.mjs) and renders every view:
 * overview, directions, timed test, review page, end-of-module screen, and results.
 */
(() => {
  'use strict';

  const EXAM = window.SAT_EXAM;
  const app = document.getElementById('app');
  const modalRoot = document.getElementById('modal-root');
  const toastEl = document.getElementById('toast');

  if (!EXAM || !Array.isArray(EXAM.modules)) {
    app.innerHTML = `<main class="boot-error"><h1>Exam content not found</h1>
      <p>The file <code>data/bundle.js</code> is missing or empty. Open a terminal in the project folder,
      run <code>node scripts/build.mjs</code>, then reload this page.</p></main>`;
    return;
  }

  const LETTERS = ['A', 'B', 'C', 'D'];
  const DIFFICULTIES = ['EASY', 'MEDIUM', 'HARD'];
  const STORE_KEY = `sat-mock-${EXAM.form}-progress-v1`;
  const PREF_KEY = `sat-mock-${EXAM.form}-prefs-v1`;

  // Browser storage can be unavailable (private windows, blocked site data). Progress then lives in memory only.
  const store = {
    read(key, fallback) {
      try {
        const raw = localStorage.getItem(key);
        return raw ? JSON.parse(raw) : fallback;
      } catch {
        return fallback;
      }
    },
    write(key, value) {
      try {
        localStorage.setItem(key, JSON.stringify(value));
      } catch {
        /* memory only */
      }
    },
  };

  const prefs = { studyAids: false, theme: 'auto', timerHidden: false, ...store.read(PREF_KEY, {}) };
  const progress = store.read(STORE_KEY, null) || {};
  progress.modules = progress.modules || {};

  const ui = { view: 'home', moduleId: null, sub: 'question', navOpen: false, strikeMode: false, filter: 'all', warned: false };
  let lastFocus = null;

  /* ---------- Helpers ---------- */

  const $ = (sel, el = document) => el.querySelector(sel);
  const $$ = (sel, el = document) => [...el.querySelectorAll(sel)];
  const esc = (s) =>
    String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const clock = (sec) => {
    const s = Math.max(0, Math.round(sec));
    return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
  };
  const blanks = (html) => html.replace(/_{4,}/g, '<span class="blank"><span class="sr-only">blank</span></span>');
  const hasAnswer = (v) => v !== undefined && v !== null && String(v).trim() !== '';

  const metaOf = (id) => EXAM.modules.find((m) => m.id === id);
  const contentOf = (id) => (EXAM.content && EXAM.content[id]) || null;
  const moduleHeading = (meta) => `Section ${meta.section === 'Math' ? 2 : 1}, Module ${meta.module}: ${meta.section}`;
  const moduleName = (meta) => `${meta.section}, Module ${meta.module}`;

  const ICON = {
    flag: `<svg class="ico" viewBox="0 0 20 20" aria-hidden="true"><path d="M5 18V2.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><path class="flag-fill" d="M5.5 3h10l-2.6 3.8L15.5 10.6h-10z" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg>`,
    caret: `<svg class="ico caret" viewBox="0 0 20 20" aria-hidden="true"><path d="M5 12.5 10 7.5l5 5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
    close: `<svg class="ico" viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>`,
    check: `<svg class="ico" viewBox="0 0 20 20" aria-hidden="true"><path d="m4.5 10.5 3.5 3.5 7.5-8" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
    cross: `<svg class="ico" viewBox="0 0 20 20" aria-hidden="true"><path d="m5.5 5.5 9 9m0-9-9 9" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>`,
    dash: `<svg class="ico" viewBox="0 0 20 20" aria-hidden="true"><path d="M5 10h10" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg>`,
  };

  /* ---------- State ---------- */

  function stateOf(id) {
    if (!progress.modules[id]) {
      progress.modules[id] = {
        status: 'not-started',
        idx: 0,
        answers: {},
        marked: {},
        struck: {},
        time: {},
        remaining: metaOf(id).minutes * 60,
        startedAt: null,
        submittedAt: null,
        autoSubmitted: false,
      };
    }
    return progress.modules[id];
  }

  const save = () => store.write(STORE_KEY, progress);
  const savePrefs = () => store.write(PREF_KEY, prefs);
  const currentModule = () => contentOf(ui.moduleId);
  const currentQuestion = () => currentModule().questions[stateOf(ui.moduleId).idx];

  // pending: content not generated yet; locked: previous module not submitted.
  function availability(meta) {
    if (!contentOf(meta.id)) return 'pending';
    const own = progress.modules[meta.id]?.status;
    if (own === 'submitted' || own === 'in-progress') return own;
    const prev = EXAM.modules.find((m) => m.sequence === meta.sequence - 1);
    if (prev && progress.modules[prev.id]?.status !== 'submitted') return 'locked';
    return 'not-started';
  }

  /* ---------- Scoring ---------- */

  function toNumber(s) {
    if (/^-?(\d+\.?\d*|\.\d+)$/.test(s)) return Number(s);
    const f = s.match(/^(-?\d+)\/(\d+)$/);
    return f && Number(f[2]) !== 0 ? Number(f[1]) / Number(f[2]) : null;
  }

  // Grid-in answers: exact match against the accepted list, or numerically equal (1/2 = .5 = 0.5).
  function sprMatches(response, accepted) {
    const clean = (s) => String(s).trim().replace(/\s+/g, '');
    const r = clean(response);
    const rn = toNumber(r);
    return [].concat(accepted).some((a) => {
      const c = clean(a);
      if (c === r) return true;
      const an = toNumber(c);
      return rn !== null && an !== null && Math.abs(an - rn) < 1e-9;
    });
  }

  const isCorrect = (q, r) => hasAnswer(r) && (q.type === 'spr' ? sprMatches(r, q.answer) : r === q.answer);

  function tally(rows, key, order = []) {
    const groups = new Map(order.map((k) => [k, { name: k, total: 0, correct: 0 }]));
    rows.forEach((r) => {
      const k = r.q[key];
      if (!groups.has(k)) groups.set(k, { name: k, total: 0, correct: 0 });
      const g = groups.get(k);
      g.total += 1;
      if (r.correct) g.correct += 1;
    });
    return [...groups.values()].filter((g) => g.total > 0);
  }

  function grade(id) {
    const meta = metaOf(id);
    const st = stateOf(id);
    const rows = contentOf(id).questions.map((q) => {
      const response = st.answers[q.id];
      return {
        q,
        response,
        answered: hasAnswer(response),
        correct: isCorrect(q, response),
        seconds: st.time[q.id] || 0,
        marked: Boolean(st.marked[q.id]),
      };
    });
    return {
      rows,
      total: rows.length,
      correct: rows.filter((r) => r.correct).length,
      answered: rows.filter((r) => r.answered).length,
      overTarget: rows.filter((r) => r.seconds > r.q.targetSeconds).length,
      byDomain: tally(rows, 'domain'),
      byDifficulty: tally(rows, 'difficulty', DIFFICULTIES),
      timeUsed: meta.minutes * 60 - st.remaining,
    };
  }

  /* ---------- Clock ---------- */

  let ticker = null;
  let lastTick = 0;
  let unsaved = 0;

  function startClock() {
    stopClock();
    lastTick = performance.now();
    ticker = setInterval(tick, 250);
  }

  function stopClock() {
    clearInterval(ticker);
    ticker = null;
  }

  function tick() {
    const now = performance.now();
    const dt = (now - lastTick) / 1000;
    lastTick = now;
    const st = stateOf(ui.moduleId);
    st.remaining = Math.max(0, st.remaining - dt);
    if (ui.sub === 'question') {
      const q = currentQuestion();
      st.time[q.id] = (st.time[q.id] || 0) + dt;
    }
    unsaved += dt;
    if (unsaved >= 5) {
      unsaved = 0;
      save();
    }
    if (!ui.warned && st.remaining <= 300) {
      ui.warned = true;
      toast('5 minutes left in this module.');
      // As on test day, the timer reappears for the last 5 minutes.
      if (prefs.timerHidden) {
        prefs.timerHidden = false;
        savePrefs();
        swap('.test-bar', testBar(metaOf(ui.moduleId)));
      }
    }
    paintClock();
    if (st.remaining <= 0) submitModule(true);
  }

  function paceInfo(st) {
    const meta = metaOf(ui.moduleId);
    const elapsed = meta.minutes * 60 - st.remaining;
    const planned = currentModule().questions.slice(0, st.idx).reduce((s, q) => s + q.targetSeconds, 0);
    return planned - elapsed;
  }

  function paintClock() {
    const st = stateOf(ui.moduleId);
    const el = $('#clock');
    if (el) {
      el.textContent = clock(Math.ceil(st.remaining));
      el.classList.toggle('is-low', st.remaining <= 300);
    }
    const pace = $('#pace');
    if (pace) {
      const diff = paceInfo(st);
      pace.textContent =
        Math.abs(diff) < 15 ? 'Pace: on target' : diff > 0 ? `Pace: ${clock(diff)} ahead` : `Pace: ${clock(-diff)} behind`;
      pace.classList.toggle('is-behind', diff < -60);
    }
  }

  /* ---------- Rendering: shared pieces ---------- */

  function render() {
    applyTheme();
    const views = { home: viewHome, directions: viewDirections, test: viewTest, end: viewEnd, results: viewResults };
    app.innerHTML = views[ui.view]();
    app.dataset.view = ui.view;
    if (ui.view === 'test') paintClock();
  }

  function swap(selector, html) {
    const el = $(selector);
    if (el) el.outerHTML = html;
  }

  function focusSoon(selector) {
    requestAnimationFrame(() => $(selector)?.focus({ preventScroll: true }));
  }

  function applyTheme() {
    if (prefs.theme === 'light' || prefs.theme === 'dark') document.documentElement.dataset.theme = prefs.theme;
    else delete document.documentElement.dataset.theme;
  }

  function stimulus(q) {
    const intro = q.intro ? `<p class="stim-intro">${esc(q.intro)}</p>` : '';
    const texts = (q.passages || [])
      .map((p) => {
        const isBlock = /^\s*<(ul|ol|p|table|div)\b/i.test(p.html);
        const body = isBlock ? blanks(p.html) : `<p>${blanks(p.html)}</p>`;
        return `<div class="passage">${p.label ? `<h3 class="passage-label">${esc(p.label)}</h3>` : ''}${body}</div>`;
      })
      .join('');
    return figure(q.figure) + intro + texts;
  }

  function figure(fig) {
    if (!fig) return '';
    if (fig.type === 'table') return tableFigure(fig);
    if (fig.type === 'bar') return barFigure(fig);
    return '';
  }

  function tableFigure(fig) {
    const head = fig.columns.map((c) => `<th scope="col">${esc(c)}</th>`).join('');
    const body = fig.rows
      .map((r) => `<tr>${r.map((c, i) => (i === 0 ? `<th scope="row">${esc(c)}</th>` : `<td>${esc(c)}</td>`)).join('')}</tr>`)
      .join('');
    return `<figure class="fig">
      <figcaption class="fig-title">${esc(fig.title)}</figcaption>
      <div class="table-wrap"><table class="data-table"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>
      ${fig.note ? `<p class="fig-note">${esc(fig.note)}</p>` : ''}
    </figure>`;
  }

  let chartSeq = 0;
  function barFigure(fig) {
    const W = 560;
    const H = 320;
    const m = { t: 24, r: 12, b: 44, l: 64 };
    const iw = W - m.l - m.r;
    const ih = H - m.t - m.b;
    const y = (v) => m.t + ih - (v / fig.yMax) * ih;
    const band = iw / fig.categories.length;
    const groupW = band * 0.64;
    const barW = groupW / fig.series.length;
    const hatchId = `hatch-${++chartSeq}`;

    let grid = '';
    for (let v = 0; v <= fig.yMax + 1e-9; v += fig.yStep) {
      grid += `<line x1="${m.l}" x2="${W - m.r}" y1="${y(v)}" y2="${y(v)}" class="${v === 0 ? 'axis' : 'grid'}"/>`;
      grid += `<text x="${m.l - 10}" y="${y(v)}" class="tick" text-anchor="end" dominant-baseline="middle">${v}</text>`;
    }

    let bars = '';
    fig.categories.forEach((cat, ci) => {
      const gx = m.l + ci * band + (band - groupW) / 2;
      fig.series.forEach((s, si) => {
        const v = s.values[ci];
        const x = gx + si * barW + 3;
        const w = barW - 6;
        const top = y(v);
        const fill = si === 1 ? `fill="url(#${hatchId})"` : `class="s${si}"`;
        bars += `<rect x="${x}" y="${top}" width="${w}" height="${m.t + ih - top}" rx="2" ${fill}/>`;
        if (fig.showValues) bars += `<text x="${x + w / 2}" y="${top - 7}" class="val" text-anchor="middle">${v}</text>`;
      });
      bars += `<text x="${m.l + ci * band + band / 2}" y="${m.t + ih + 26}" text-anchor="middle">${esc(cat)}</text>`;
    });

    const defs = `<defs><pattern id="${hatchId}" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
      <rect width="6" height="6" class="hatch-bg"/><line x1="0" y1="0" x2="0" y2="6" class="hatch-line"/></pattern></defs>`;
    const yLabel = `<text transform="translate(16 ${m.t + ih / 2}) rotate(-90)" class="axis-label" text-anchor="middle">${esc(fig.yLabel)}</text>`;
    const legend = `<ul class="legend">${fig.series.map((s, si) => `<li><span class="swatch s${si}"></span>${esc(s.name)}</li>`).join('')}</ul>`;
    const srTable = `<table class="sr-only"><caption>${esc(fig.title)} (${esc(fig.yLabel)})</caption>
      <thead><tr><th scope="col">Category</th>${fig.series.map((s) => `<th scope="col">${esc(s.name)}</th>`).join('')}</tr></thead>
      <tbody>${fig.categories.map((c, ci) => `<tr><th scope="row">${esc(c)}</th>${fig.series.map((s) => `<td>${s.values[ci]}</td>`).join('')}</tr>`).join('')}</tbody></table>`;

    return `<figure class="fig">
      <figcaption class="fig-title">${esc(fig.title)}</figcaption>
      <svg class="chart" viewBox="0 0 ${W} ${H}" aria-hidden="true" focusable="false">${defs}${grid}${bars}${yLabel}</svg>
      ${legend}${srTable}
    </figure>`;
  }

  function gridLegend() {
    return `<ul class="grid-legend">
      <li><span class="legend-pin" aria-hidden="true"></span>Current</li>
      <li><span class="legend-cell legend-cell--open" aria-hidden="true"></span>Unanswered</li>
      <li><span class="legend-cell legend-cell--done" aria-hidden="true"></span>Answered</li>
      <li><span class="qflag" aria-hidden="true">${ICON.flag}</span>For review</li>
    </ul>`;
  }

  function questionGrid(mod, st, currentIdx) {
    const cells = mod.questions
      .map((q, i) => {
        const answered = hasAnswer(st.answers[q.id]);
        const marked = Boolean(st.marked[q.id]);
        const current = i === currentIdx;
        const label = [
          `Question ${q.number}`,
          current ? 'current' : '',
          answered ? 'answered' : 'unanswered',
          marked ? 'marked for review' : '',
        ]
          .filter(Boolean)
          .join(', ');
        const cls = ['qcell', answered && 'is-answered', marked && 'is-marked', current && 'is-current'].filter(Boolean).join(' ');
        return `<li><button class="${cls}" data-act="goto" data-idx="${i}" aria-label="${label}">${q.number}${
          marked ? `<span class="qflag" aria-hidden="true">${ICON.flag}</span>` : ''
        }</button></li>`;
      })
      .join('');
    return `<ol class="qgrid">${cells}</ol>`;
  }

  /* ---------- View: overview ---------- */

  function viewHome() {
    const items = [];
    EXAM.modules.forEach((meta) => {
      items.push(routeStop(meta));
      if (meta.id === EXAM.breakAfter) {
        items.push(`<li class="route-break">${EXAM.breakMinutes}-minute break between sections</li>`);
      }
    });
    const totalQuestions = EXAM.modules.reduce((s, m) => s + m.questions, 0);
    return `<div class="home">
      <header class="cover">
        <p class="cover-form">Form ${esc(EXAM.form)}, ${esc(EXAM.edition.toLowerCase())}</p>
        <h1 class="cover-title" tabindex="-1">${esc(EXAM.title)}</h1>
        <p class="cover-lede">A full-length practice test in the adaptive digital format: two sections, four timed modules,
          ${totalQuestions} questions. Topics come from every region of the world, and all measurements are metric.</p>
        ${settingsBlock()}
      </header>
      <section class="route" aria-label="Test modules">
        <ol class="route-list">${items.join('')}</ol>
        <p class="route-after">The scoring guide, post-test analysis, and pacing reference card come after Module 4.</p>
      </section>
    </div>`;
  }

  function routeStop(meta) {
    const state = availability(meta);
    const st = progress.modules[meta.id];
    let status = '';
    let actions = '';
    let style = '';
    if (state === 'pending') {
      status = 'Not generated yet. It will appear here when it is ready.';
    } else if (state === 'locked') {
      status = `Unlocks after you submit Module ${meta.sequence - 1}.`;
    } else if (state === 'not-started') {
      status = 'Ready when you are.';
      actions = `<button class="btn btn-primary" data-act="open" data-id="${meta.id}">Start Module ${meta.sequence}</button>`;
    } else if (state === 'in-progress') {
      const total = contentOf(meta.id).questions.length;
      const answered = Object.values(st.answers).filter(hasAnswer).length;
      status = `In progress: ${clock(st.remaining)} left, ${answered} of ${total} answered.`;
      style = ` style="--done: ${Math.round((answered / total) * 100)}%"`;
      actions = `<button class="btn btn-primary" data-act="resume" data-id="${meta.id}">Resume</button>
        <button class="btn btn-quiet" data-act="reset" data-id="${meta.id}">Restart</button>`;
    } else {
      const g = grade(meta.id);
      status = `Submitted. Raw score ${g.correct} of ${g.total}.`;
      actions = `<button class="btn btn-outline" data-act="results" data-id="${meta.id}">Review answers</button>
        <button class="btn btn-quiet" data-act="reset" data-id="${meta.id}">Retake</button>`;
    }
    return `<li class="stop is-${state}"${style}>
      <span class="stop-bubble" aria-hidden="true">${meta.sequence}</span>
      <div class="stop-body">
        <h2 class="stop-title"><span class="sr-only">Module ${meta.sequence}: </span>${moduleName(meta)}</h2>
        <p class="stop-meta">${meta.minutes} minutes, ${meta.questions} questions</p>
        <p class="stop-status">${status}</p>
      </div>
      ${actions ? `<div class="stop-actions">${actions}</div>` : ''}
    </li>`;
  }

  function settingsBlock() {
    const themes = [
      ['auto', 'Match device'],
      ['light', 'Light'],
      ['dark', 'Dark'],
    ];
    return `<section class="settings" aria-labelledby="settings-title">
      <h2 class="settings-title" id="settings-title">Test settings</h2>
      <label class="toggle">
        <input type="checkbox" data-pref="studyAids" ${prefs.studyAids ? 'checked' : ''}>
        <span class="toggle-track" aria-hidden="true"></span>
        <span>Show study aids while testing</span>
      </label>
      <p class="hint">Adds each question’s skill, difficulty tag, target time, and your pace. Leave this off for realistic
        test conditions. Everything appears in the review after each module either way.</p>
      <fieldset class="seg">
        <legend>Theme</legend>
        <div class="seg-options">${themes
          .map(
            ([value, label]) =>
              `<label><input type="radio" name="theme" value="${value}" data-pref="theme" ${prefs.theme === value ? 'checked' : ''}><span>${label}</span></label>`,
          )
          .join('')}</div>
      </fieldset>
      <details class="keys">
        <summary>Keyboard shortcuts</summary>
        <dl>
          <dt><kbd>←</kbd> <kbd>→</kbd></dt><dd>Previous or next question</dd>
          <dt><kbd>A</kbd>–<kbd>D</kbd></dt><dd>Choose an answer</dd>
          <dt><kbd>M</kbd></dt><dd>Mark or unmark for review</dd>
          <dt><kbd>Esc</kbd></dt><dd>Close the navigator or a dialog</dd>
        </dl>
      </details>
    </section>`;
  }

  /* ---------- View: directions ---------- */

  function viewDirections() {
    const meta = metaOf(ui.moduleId);
    const mod = currentModule();
    return `<main class="directions">
      <p class="directions-context">${moduleHeading(meta)}</p>
      <h1 tabindex="-1">Directions</h1>
      <p class="directions-meta">${mod.questions.length} questions, ${meta.minutes} minutes</p>
      ${mod.directions.map((p) => `<p>${esc(p)}</p>`).join('')}
      <h2>Test tools</h2>
      <ul class="tool-list">
        <li><strong>Mark for review</strong> flags a question so you can find it quickly later.</li>
        <li><strong>Cross out</strong> (the <span style="text-decoration: line-through">ABC</span> button) lets you strike through choices you have ruled out.</li>
        <li><strong>Question navigator</strong> at the bottom of the screen shows which questions are answered, unanswered, or marked.</li>
        <li><strong>Save and exit</strong> keeps your answers and pauses the clock. This is a practice feature; the real test has no pause.</li>
      </ul>
      <div class="directions-actions">
        <button class="btn btn-outline" data-act="home">Back to overview</button>
        <button class="btn btn-primary" data-act="begin">Start module</button>
      </div>
      <p class="hint">The ${meta.minutes}-minute timer starts when you select Start module.</p>
    </main>`;
  }

  /* ---------- View: test ---------- */

  function viewTest() {
    const meta = metaOf(ui.moduleId);
    const mod = currentModule();
    const st = stateOf(ui.moduleId);
    return `<div class="test">
      ${testBar(meta)}
      ${ui.sub === 'check' ? checkPage(meta, mod, st) : questionStage(st)}
      ${testFoot(meta, mod, st)}
    </div>`;
  }

  function testBar(meta) {
    const clockHtml = prefs.timerHidden
      ? `<span class="clock-hidden">Timer hidden</span>`
      : `<span class="sr-only">Time remaining</span><span id="clock" class="clock" role="timer"></span>`;
    return `<header class="test-bar">
      <div class="bar-start">
        <p class="bar-title">${moduleHeading(meta)}</p>
        <button class="text-btn" data-act="directions">Directions</button>
      </div>
      <div class="bar-clock">
        ${clockHtml}
        <button class="chip" data-act="toggle-timer">${prefs.timerHidden ? 'Show timer' : 'Hide'}</button>
      </div>
      <div class="bar-end">
        <label class="toggle toggle--compact">
          <input type="checkbox" data-pref="studyAids" ${prefs.studyAids ? 'checked' : ''}>
          <span class="toggle-track" aria-hidden="true"></span>
          <span>Study aids</span>
        </label>
        <button class="text-btn" data-act="save-exit">Save and exit</button>
      </div>
    </header>`;
  }

  function questionStage(st) {
    const q = currentQuestion();
    const hasStimulus = Boolean((q.passages && q.passages.length) || q.figure);
    const left = hasStimulus
      ? `<section class="pane pane--stimulus" aria-label="Passage for question ${q.number}"><div class="pane-inner">${stimulus(q)}</div></section>
         <div class="stage-divider" aria-hidden="true"></div>`
      : '';
    return `<main class="stage${hasStimulus ? ' stage--split' : ''}">
      ${left}
      <section class="pane pane--question" id="qpane" aria-label="Question ${q.number}">
        <div class="pane-inner">${questionPane(q, st)}</div>
      </section>
    </main>`;
  }

  function questionPane(q, st) {
    const marked = Boolean(st.marked[q.id]);
    const response = st.answers[q.id];
    const aids = prefs.studyAids
      ? `<p class="aids">
          <span class="tag tag--${q.difficulty.toLowerCase()}">[${q.difficulty}]</span>
          <span>${esc(q.domain)} / ${esc(q.skill)}</span>
          <span>⏱ Target: ${q.targetSeconds} seconds</span>
        </p>`
      : '';
    return `<div class="q-head">
        <span class="q-num"><span class="sr-only">Question </span>${q.number}</span>
        <button class="mark-btn" data-act="mark" aria-pressed="${marked}">${ICON.flag}Mark for review</button>
        ${
          q.type === 'mcq'
            ? `<button class="strike-toggle" data-act="strike-mode" aria-pressed="${ui.strikeMode}" title="Cross out answer choices"><span class="abc" aria-hidden="true">ABC</span><span class="sr-only">Cross out answer choices</span></button>`
            : ''
        }
      </div>
      ${aids}
      <h2 class="stem" id="stem-${q.id}" tabindex="-1">${q.stem}</h2>
      ${q.type === 'spr' ? sprInput(q, response) : choiceList(q, response, st.struck[q.id] || [])}`;
  }

  function choiceList(q, response, struck) {
    const rows = LETTERS.map((L) => {
      const selected = response === L;
      const out = struck.includes(L);
      const strikeBtn = ui.strikeMode
        ? `<button class="strike-btn" data-act="strike" data-letter="${L}" aria-pressed="${out}" aria-label="${out ? 'Undo cross-out of' : 'Cross out'} choice ${L}">${
            out ? 'Undo' : `<span class="strike-letter" aria-hidden="true">${L}</span>`
          }</button>`
        : '';
      return `<div class="choice-row${out ? ' is-struck' : ''}">
        <button class="choice${selected ? ' is-selected' : ''}" role="radio" aria-checked="${selected}" data-act="choose" data-letter="${L}">
          <span class="bubble" aria-hidden="true">${L}</span>
          <span class="choice-text"><span class="sr-only">${L}. </span>${q.choices[L]}${out ? '<span class="sr-only"> (crossed out)</span>' : ''}</span>
        </button>
        ${strikeBtn}
      </div>`;
    }).join('');
    return `<div class="choices" role="radiogroup" aria-labelledby="stem-${q.id}">${rows}</div>`;
  }

  function sprInput(q, response) {
    return `<div class="spr">
      <label class="spr-label" for="spr-${q.id}">Your answer</label>
      <input class="spr-input" id="spr-${q.id}" data-spr="${q.id}" inputmode="decimal" autocomplete="off" spellcheck="false" maxlength="6" value="${esc(response || '')}">
      <p class="spr-preview">Answer preview: <strong id="spr-preview">${esc(response || '')}</strong></p>
      <p class="hint">Enter a whole number, decimal, or fraction such as 3/4. Use up to 5 characters, plus a minus sign for negative answers.</p>
    </div>`;
  }

  function testFoot(meta, mod, st) {
    const start = prefs.studyAids ? `<span id="pace" class="pace"></span>` : `<span>Form ${esc(EXAM.form)}</span>`;
    if (ui.sub === 'check') {
      return `<footer class="test-foot">
        <div class="foot-start">${start}</div>
        <div class="foot-mid"></div>
        <div class="foot-end">
          <button class="btn btn-outline" data-act="leave-check">Back</button>
          <button class="btn btn-primary" data-act="submit">Submit module</button>
        </div>
      </footer>`;
    }
    const popover = ui.navOpen
      ? `<div class="navpop" id="navpop" role="dialog" aria-label="Question navigator">
          <div class="navpop-head">
            <h2>${moduleHeading(meta)} questions</h2>
            <button class="icon-btn" data-act="nav" aria-label="Close navigator">${ICON.close}</button>
          </div>
          ${gridLegend()}
          ${questionGrid(mod, st, st.idx)}
          <div class="navpop-foot"><button class="btn btn-outline" data-act="to-check">Go to review page</button></div>
        </div>`
      : '';
    return `<footer class="test-foot">
      <div class="foot-start">${start}</div>
      <div class="foot-mid">
        <button class="nav-btn" data-act="nav" aria-expanded="${ui.navOpen}" aria-controls="navpop">Question ${st.idx + 1} of ${mod.questions.length}${ICON.caret}</button>
        ${popover}
      </div>
      <div class="foot-end">
        <button class="btn btn-outline" data-act="prev" ${st.idx === 0 ? 'disabled' : ''}>Back</button>
        <button class="btn btn-primary" data-act="next">Next</button>
      </div>
    </footer>`;
  }

  function checkPage(meta, mod, st) {
    const n = mod.questions.length;
    const answered = mod.questions.filter((q) => hasAnswer(st.answers[q.id])).length;
    const marked = mod.questions.filter((q) => st.marked[q.id]).length;
    return `<main class="check">
      <div class="check-inner">
        <h1 tabindex="-1">Check your work</h1>
        <p>Select a question number to go back to it. When you’re ready, submit the module. You can’t change your answers after you submit.</p>
        <div class="check-panel">
          <div class="check-panel-head"><h2>${moduleHeading(meta)}</h2>${gridLegend()}</div>
          <p class="check-counts">${answered} of ${n} answered${marked ? `, ${marked} marked for review` : ''}</p>
          ${questionGrid(mod, st, -1)}
        </div>
      </div>
    </main>`;
  }

  /* ---------- View: end of module ---------- */

  function viewEnd() {
    const meta = metaOf(ui.moduleId);
    const st = stateOf(ui.moduleId);
    const g = grade(ui.moduleId);
    const [, rule = '', rest = ''] = meta.endMessage.match(/^(---.*?---)\s*(.*)$/) || [];
    const [, title = rest, sub = ''] = rest.match(/^(.*?\.)\s+(.*)$/) || [];
    const next = EXAM.modules.find((m) => m.sequence === meta.sequence + 1);
    let nextNote = 'The scoring guide, post-test analysis, and pacing reference card come next.';
    if (next) {
      nextNote = contentOf(next.id)
        ? `Module ${next.sequence} (${moduleName(next)}) is ready on the overview page.`
        : `Module ${next.sequence} (${moduleName(next)}) hasn’t been generated yet. It unlocks on the overview page as soon as it’s added.`;
    }
    return `<main class="end">
      <p class="end-rule">${esc(rule)}</p>
      <h1 class="end-title" tabindex="-1">${esc(title)}</h1>
      <p class="end-sub">${esc(sub)}</p>
      ${st.autoSubmitted ? `<p class="end-note">Time ran out, so your answers were submitted automatically.</p>` : ''}
      <dl class="end-stats">
        <div><dt>Raw score</dt><dd>${g.correct} / ${g.total}</dd></div>
        <div><dt>Answered</dt><dd>${g.answered} / ${g.total}</dd></div>
        <div><dt>Time used</dt><dd>${clock(g.timeUsed)}</dd></div>
      </dl>
      <div class="end-actions">
        <button class="btn btn-primary" data-act="results" data-id="${meta.id}">Review answers and explanations</button>
        <button class="btn btn-outline" data-act="home">Back to overview</button>
      </div>
      <p class="end-next">${nextNote}</p>
    </main>`;
  }

  /* ---------- View: results ---------- */

  const FILTERS = [
    ['all', 'All', () => true],
    ['wrong', 'Incorrect', (r) => r.answered && !r.correct],
    ['omitted', 'Omitted', (r) => !r.answered],
    ['marked', 'Marked', (r) => r.marked],
    ['slow', 'Over target time', (r) => r.seconds > r.q.targetSeconds],
  ];

  function viewResults() {
    const meta = metaOf(ui.moduleId);
    const mod = currentModule();
    const g = grade(ui.moduleId);
    const active = FILTERS.find(([key]) => key === ui.filter) || FILTERS[0];
    const rows = g.rows.filter(active[2]);
    const filterButtons = FILTERS.map(
      ([key, label, test]) =>
        `<button class="filter" data-act="filter" data-filter="${key}" aria-pressed="${ui.filter === key}">${label}<span class="count">${
          g.rows.filter(test).length
        }</span></button>`,
    ).join('');
    return `<div class="results">
      <header class="results-head">
        <button class="text-btn" data-act="home">Exam overview</button>
        <h1 tabindex="-1">Module ${meta.sequence} results</h1>
        <p class="results-sub">${moduleName(meta)}, Form ${esc(EXAM.form)}</p>
      </header>
      <section class="summary" aria-label="Summary">
        <div class="score"><span class="score-num">${g.correct}</span><span class="score-of">of ${g.total} correct</span></div>
        <dl class="summary-facts">
          <div><dt>Time used</dt><dd>${clock(g.timeUsed)} of ${meta.minutes}:00</dd></div>
          <div><dt>Answered</dt><dd>${g.answered} of ${g.total}</dd></div>
          <div><dt>Over target time</dt><dd>${g.overTarget} ${g.overTarget === 1 ? 'question' : 'questions'}</dd></div>
          <div><dt>Marked for review</dt><dd>${g.rows.filter((r) => r.marked).length}</dd></div>
        </dl>
        <p class="summary-note">A scaled section score needs both modules of the section. The raw-to-scaled conversion tables arrive with the scoring guide after Module 4.</p>
      </section>
      <section class="breakdown" aria-label="Score breakdown">
        <div><h2>By domain</h2>${g.byDomain.map(meter).join('')}</div>
        <div><h2>By difficulty</h2>${g.byDifficulty.map(meter).join('')}</div>
      </section>
      <section class="pacing">
        <h2>Pacing checkpoints</h2>
        ${pacingTable(meta, mod, g)}
      </section>
      <section class="review">
        <div class="review-head">
          <h2>Answers and explanations</h2>
          <div class="review-tools">
            <div class="filters" role="group" aria-label="Show questions">${filterButtons}</div>
            <button class="text-btn" data-act="expand">Expand all</button>
            <button class="text-btn" data-act="print">Print</button>
          </div>
        </div>
        ${rows.length ? `<div class="rv-list">${rows.map(reviewItem).join('')}</div>` : `<p class="empty">No questions match this filter.</p>`}
      </section>
    </div>`;
  }

  function meter(group) {
    const pct = Math.round((group.correct / group.total) * 100);
    const name = DIFFICULTIES.includes(group.name) ? `[${group.name}]` : group.name;
    return `<div class="meter-row">
      <span class="meter-name">${esc(name)}</span>
      <span class="meter-val">${group.correct} / ${group.total}</span>
      <span class="meter" aria-hidden="true"><span class="meter-fill" style="width: ${pct}%"></span></span>
    </div>`;
  }

  function pacingTable(meta, mod, g) {
    const n = mod.questions.length;
    const total = meta.minutes * 60;
    const marks = [1, 2, 3, 4].map((k) => Math.ceil((n * k) / 4));
    let target = 0;
    let yours = 0;
    let i = 0;
    const rows = marks.map((mark) => {
      for (; i < mark; i++) {
        target += mod.questions[i].targetSeconds;
        yours += g.rows[i].seconds;
      }
      const diff = yours - target;
      const status =
        Math.abs(diff) <= 30
          ? 'On target'
          : diff < 0
            ? `<span class="is-ahead">${clock(-diff)} ahead</span>`
            : `<span class="is-behind">${clock(diff)} behind</span>`;
      return `<tr><th scope="row">After question ${mark}</th><td>${clock(target)}</td><td>${clock(total - target)}</td><td>${clock(yours)}</td><td>${status}</td></tr>`;
    });
    const buffer = total - mod.questions.reduce((s, q) => s + q.targetSeconds, 0);
    return `<div class="table-wrap"><table class="data-table">
      <thead><tr><th scope="col">Checkpoint</th><th scope="col">Target time spent</th><th scope="col">Clock should show</th><th scope="col">Your time spent</th><th scope="col">Status</th></tr></thead>
      <tbody>${rows.join('')}</tbody>
    </table></div>
    <p class="hint">Target times leave ${clock(buffer)} at the end to check your work. “Your time spent” adds up the time you spent on those questions, including return visits.</p>`;
  }

  function reviewItem(r) {
    const { q } = r;
    const status = !r.answered ? 'omitted' : r.correct ? 'correct' : 'wrong';
    const label = { correct: 'Correct', wrong: 'Incorrect', omitted: 'Omitted' }[status];
    const icon = { correct: ICON.check, wrong: ICON.cross, omitted: ICON.dash }[status];
    const over = r.seconds > q.targetSeconds;
    const answerLine =
      q.type === 'spr'
        ? `<p class="rv-answer">Your answer: <strong>${hasAnswer(r.response) ? esc(r.response) : 'none'}</strong>. Accepted answers: <strong>${q.answer.map(esc).join(', ')}</strong></p>`
        : `<p class="rv-answer">Correct answer: <strong>${q.answer}</strong>${
            r.answered && !r.correct ? `. You chose <strong>${esc(r.response)}</strong>.` : ''
          }</p>`;
    return `<details class="rv rv--${status}">
      <summary class="rv-sum">
        <span class="rv-num">${q.number}</span>
        <span class="rv-skill"><span>${esc(q.skill)}</span><small>${esc(q.domain)}</small></span>
        <span class="tag tag--${q.difficulty.toLowerCase()}">[${q.difficulty}]</span>
        <span class="rv-status">${icon}${label}</span>
        <span class="rv-time${over ? ' is-over' : ''}"><span class="sr-only">Your time </span>${clock(r.seconds)}<span class="rv-target"> / ${clock(q.targetSeconds)}</span></span>
      </summary>
      <div class="rv-body">
        <div class="rv-stim">${stimulus(q)}</div>
        <p class="rv-stem">${q.stem}</p>
        ${q.type === 'spr' ? '' : reviewChoices(q, r)}
        ${answerLine}
        <div class="rv-expl">${explanation(q)}</div>
        <p class="rv-timing">⏱ Target: ${q.targetSeconds} seconds. Your time: ${Math.round(r.seconds)} seconds.</p>
      </div>
    </details>`;
  }

  function reviewChoices(q, r) {
    const items = LETTERS.map((L) => {
      const isKey = L === q.answer;
      const isYours = r.response === L;
      const badges = [
        isKey ? '<span class="badge badge--key">Correct answer</span>' : '',
        isYours ? `<span class="badge ${isKey ? 'badge--yours-right' : 'badge--yours-wrong'}">Your answer</span>` : '',
      ].join('');
      const cls = ['rv-choice', isKey && 'is-key', isYours && !isKey && 'is-miss'].filter(Boolean).join(' ');
      return `<li class="${cls}"><span class="bubble" aria-hidden="true">${L}</span><span class="rv-choice-text"><span class="sr-only">${L}. </span>${q.choices[L]}</span>${badges}</li>`;
    }).join('');
    return `<ul class="rv-choices">${items}</ul>`;
  }

  function explanation(q) {
    const tip = q.tip ? `<aside class="tip"><h3>Tip</h3><p>${q.tip}</p></aside>` : '';
    if (q.type === 'spr') {
      return `<h3>Step-by-step solution</h3><ol class="solution">${q.solution.map((s) => `<li>${s}</li>`).join('')}</ol>${tip}`;
    }
    const wrong = LETTERS.filter((L) => L !== q.answer && q.distractors?.[L]);
    return `<h3>Key explanation</h3><p>${q.explanation}</p>
      <h3>Why the other choices are wrong</h3>
      <dl class="distractors">${wrong.map((L) => `<div><dt>Choice ${L}</dt><dd>${q.distractors[L]}</dd></div>`).join('')}</dl>
      ${tip}`;
  }

  /* ---------- Modal + toast ---------- */

  function openModal(title, body, actions) {
    lastFocus = document.activeElement;
    modalRoot.innerHTML = `<div class="scrim" data-act="close-modal"></div>
      <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">
        <h2 id="modal-title">${title}</h2>
        <div class="modal-body">${body}</div>
        <div class="modal-actions">${actions}</div>
      </div>`;
    modalRoot.hidden = false;
    $('.modal-actions button:last-child', modalRoot)?.focus();
  }

  function closeModal() {
    if (modalRoot.hidden) return;
    modalRoot.hidden = true;
    modalRoot.innerHTML = '';
    if (lastFocus && document.contains(lastFocus)) lastFocus.focus();
  }

  function trapFocus(e) {
    const focusable = $$('button, [href], input, [tabindex]:not([tabindex="-1"])', modalRoot).filter((el) => !el.disabled);
    if (!focusable.length) return;
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  let toastTimer = null;
  function toast(message) {
    toastEl.textContent = message;
    toastEl.classList.add('is-on');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toastEl.classList.remove('is-on'), 4000);
  }

  /* ---------- Actions ---------- */

  function enterTest(id) {
    ui.moduleId = id;
    ui.view = 'test';
    ui.sub = 'question';
    ui.navOpen = false;
    ui.strikeMode = false;
    ui.warned = stateOf(id).remaining <= 300;
    render();
    startClock();
    focusSoon('.stem');
  }

  function go(index) {
    const st = stateOf(ui.moduleId);
    st.idx = Math.max(0, Math.min(currentModule().questions.length - 1, index));
    ui.sub = 'question';
    ui.navOpen = false;
    save();
    render();
    focusSoon('.stem');
  }

  function patchQuestion(refocus) {
    const pane = $('#qpane .pane-inner');
    if (pane) pane.innerHTML = questionPane(currentQuestion(), stateOf(ui.moduleId));
    if (refocus) $(refocus)?.focus({ preventScroll: true });
  }

  function renderFoot() {
    swap('.test-foot', testFoot(metaOf(ui.moduleId), currentModule(), stateOf(ui.moduleId)));
    paintClock();
  }

  function choose(letter) {
    const q = currentQuestion();
    if (q.type !== 'mcq') return;
    const st = stateOf(ui.moduleId);
    st.answers[q.id] = letter;
    st.struck[q.id] = (st.struck[q.id] || []).filter((L) => L !== letter);
    save();
    patchQuestion(`.choice[data-letter="${letter}"]`);
  }

  function toggleStrike(letter) {
    const q = currentQuestion();
    const st = stateOf(ui.moduleId);
    const list = st.struck[q.id] || [];
    if (list.includes(letter)) {
      st.struck[q.id] = list.filter((L) => L !== letter);
    } else {
      st.struck[q.id] = [...list, letter];
      if (st.answers[q.id] === letter) delete st.answers[q.id];
    }
    save();
    patchQuestion(`.strike-btn[data-letter="${letter}"]`);
  }

  function toggleMark() {
    const q = currentQuestion();
    const st = stateOf(ui.moduleId);
    if (st.marked[q.id]) delete st.marked[q.id];
    else st.marked[q.id] = true;
    save();
    patchQuestion('.mark-btn');
    if (ui.navOpen) renderFoot();
  }

  function next() {
    const st = stateOf(ui.moduleId);
    if (st.idx < currentModule().questions.length - 1) return go(st.idx + 1);
    showCheckPage();
  }

  function showCheckPage() {
    ui.sub = 'check';
    ui.navOpen = false;
    render();
    focusSoon('.check h1');
  }

  function confirmSubmit() {
    const meta = metaOf(ui.moduleId);
    const mod = currentModule();
    const st = stateOf(ui.moduleId);
    const unanswered = mod.questions.filter((q) => !hasAnswer(st.answers[q.id])).length;
    const marked = mod.questions.filter((q) => st.marked[q.id]).length;
    const issues = [
      unanswered ? `${unanswered} unanswered ${unanswered === 1 ? 'question' : 'questions'}` : '',
      marked ? `${marked} marked for review` : '',
    ]
      .filter(Boolean)
      .join(' and ');
    openModal(
      `Submit Module ${meta.sequence}?`,
      `<p>${issues ? `You have ${issues}.` : 'Every question has an answer.'} After you submit, you can’t change your answers.</p>
       <p>${clock(Math.ceil(st.remaining))} is left on the clock.</p>`,
      `<button class="btn btn-outline" data-act="close-modal">Keep working</button>
       <button class="btn btn-primary" data-act="confirm-submit">Submit module</button>`,
    );
  }

  function submitModule(auto) {
    const st = stateOf(ui.moduleId);
    stopClock();
    closeModal();
    st.status = 'submitted';
    st.submittedAt = Date.now();
    st.autoSubmitted = Boolean(auto);
    save();
    ui.view = 'end';
    ui.sub = 'question';
    ui.navOpen = false;
    ui.strikeMode = false;
    render();
    focusSoon('.end-title');
  }

  function showDirections() {
    const meta = metaOf(ui.moduleId);
    openModal(
      'Directions',
      `<p><strong>${moduleHeading(meta)}</strong></p>${currentModule().directions.map((p) => `<p>${esc(p)}</p>`).join('')}`,
      `<button class="btn btn-primary" data-act="close-modal">Close</button>`,
    );
  }

  function confirmReset(id) {
    const meta = metaOf(id);
    openModal(
      `Clear Module ${meta.sequence}?`,
      `<p>This deletes your answers, review marks, and timing for ${moduleName(meta)} so you can take it again from the start.</p>`,
      `<button class="btn btn-outline" data-act="close-modal">Cancel</button>
       <button class="btn btn-primary" data-act="confirm-reset" data-id="${id}">Clear and restart</button>`,
    );
  }

  const actions = {
    open: (el) => {
      ui.moduleId = el.dataset.id;
      ui.view = 'directions';
      render();
      focusSoon('.directions h1');
    },
    begin: () => {
      const st = stateOf(ui.moduleId);
      st.status = 'in-progress';
      st.startedAt = st.startedAt || Date.now();
      save();
      enterTest(ui.moduleId);
    },
    resume: (el) => enterTest(el.dataset.id),
    results: (el) => {
      ui.moduleId = el.dataset.id;
      ui.filter = 'all';
      ui.view = 'results';
      render();
      window.scrollTo(0, 0);
      focusSoon('.results-head h1');
    },
    home: () => {
      ui.view = 'home';
      render();
      window.scrollTo(0, 0);
    },
    reset: (el) => confirmReset(el.dataset.id),
    'confirm-reset': (el) => {
      delete progress.modules[el.dataset.id];
      save();
      closeModal();
      render();
    },
    choose: (el) => choose(el.dataset.letter),
    strike: (el) => toggleStrike(el.dataset.letter),
    'strike-mode': () => {
      ui.strikeMode = !ui.strikeMode;
      patchQuestion('.strike-toggle');
    },
    mark: toggleMark,
    prev: () => go(stateOf(ui.moduleId).idx - 1),
    next,
    nav: () => {
      ui.navOpen = !ui.navOpen;
      renderFoot();
      focusSoon(ui.navOpen ? '.navpop .qcell.is-current' : '.nav-btn');
    },
    goto: (el) => go(Number(el.dataset.idx)),
    'to-check': showCheckPage,
    'leave-check': () => go(stateOf(ui.moduleId).idx),
    submit: confirmSubmit,
    'confirm-submit': () => submitModule(false),
    'close-modal': closeModal,
    directions: showDirections,
    'toggle-timer': () => {
      prefs.timerHidden = !prefs.timerHidden;
      savePrefs();
      swap('.test-bar', testBar(metaOf(ui.moduleId)));
      paintClock();
      focusSoon('[data-act="toggle-timer"]');
    },
    'save-exit': () => {
      save();
      stopClock();
      ui.view = 'home';
      ui.navOpen = false;
      render();
      toast('Progress saved. The clock is paused until you resume.');
    },
    filter: (el) => {
      ui.filter = el.dataset.filter;
      render();
      focusSoon(`[data-filter="${ui.filter}"]`);
    },
    expand: (el) => {
      const items = $$('.rv');
      const open = !items.every((d) => d.open);
      items.forEach((d) => (d.open = open));
      el.textContent = open ? 'Collapse all' : 'Expand all';
    },
    print: () => window.print(),
  };

  /* ---------- Events ---------- */

  document.addEventListener('click', (e) => {
    const target = e.target.closest('[data-act]');
    if (ui.navOpen && !e.target.closest('.navpop, .nav-btn')) {
      ui.navOpen = false;
      renderFoot();
    }
    if (!target || target.disabled) return;
    const fn = actions[target.dataset.act];
    if (fn) fn(target, e);
  });

  document.addEventListener('change', (e) => {
    const el = e.target;
    if (el.dataset.pref === 'studyAids') {
      prefs.studyAids = el.checked;
      savePrefs();
      if (ui.view === 'test') {
        if (ui.sub === 'question') patchQuestion();
        renderFoot();
      }
    } else if (el.dataset.pref === 'theme') {
      prefs.theme = el.value;
      savePrefs();
      applyTheme();
    }
  });

  document.addEventListener('input', (e) => {
    const el = e.target;
    if (!el.dataset.spr) return;
    const cleaned = el.value.replace(/[^0-9./-]/g, '');
    if (cleaned !== el.value) el.value = cleaned;
    const st = stateOf(ui.moduleId);
    if (cleaned) st.answers[el.dataset.spr] = cleaned;
    else delete st.answers[el.dataset.spr];
    const preview = $('#spr-preview');
    if (preview) preview.textContent = cleaned;
    save();
  });

  document.addEventListener('keydown', (e) => {
    if (!modalRoot.hidden) {
      if (e.key === 'Escape') closeModal();
      else if (e.key === 'Tab') trapFocus(e);
      return;
    }
    if (ui.view !== 'test') return;
    if (e.key === 'Escape' && ui.navOpen) {
      ui.navOpen = false;
      renderFoot();
      focusSoon('.nav-btn');
      return;
    }
    if (ui.sub !== 'question' || e.altKey || e.ctrlKey || e.metaKey) return;
    if (e.target instanceof Element && e.target.closest('input, textarea, select, [contenteditable="true"]')) return;
    const key = e.key.toLowerCase();
    if (e.key === 'ArrowRight') {
      e.preventDefault();
      next();
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      if (stateOf(ui.moduleId).idx > 0) actions.prev();
    } else if (['a', 'b', 'c', 'd'].includes(key) && currentQuestion().type === 'mcq') {
      e.preventDefault();
      choose(key.toUpperCase());
    } else if (key === 'm') {
      e.preventDefault();
      toggleMark();
    }
  });

  window.addEventListener('pagehide', save);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) save();
  });
  window.addEventListener('beforeprint', () => $$('.rv').forEach((d) => (d.open = true)));

  render();
})();
